<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { apiDelete,apiGet,apiPost } from '../api/client';import KpiGrid from '../components/KpiGrid.vue';import PageHeader from '../components/PageHeader.vue';import type { ReportItem } from '../types/admin'
import { useAuthStore } from '../stores/auth';const auth=useAuthStore()
const items=ref<ReportItem[]>([]);const loading=ref(true);const dialog=ref(false);const form=ref({name:'',type:'route',dateRange:'近 30 天',dimension:'城市'})
const kpis=computed(()=>[{label:'报表任务',value:items.value.length,delta:'全部历史'},{label:'已完成',value:items.value.filter(x=>x.status==='done').length,delta:'可下载'},{label:'处理中',value:items.value.filter(x=>x.status==='processing').length,delta:'生成中',warn:true},{label:'失败',value:items.value.filter(x=>x.status==='failed').length,delta:'需重试',warn:true}])
async function load(){loading.value=true;try{items.value=await apiGet<ReportItem[]>('/admin/reports')}finally{loading.value=false}}
async function create(){await apiPost('/admin/reports',form.value);dialog.value=false;ElMessage.success('报表任务已写入数据库');await load()}
async function remove(tableRow:unknown){const row=tableRow as ReportItem;await ElMessageBox.confirm(`确认删除「${row.name}」？`,'删除报表',{type:'warning'});await apiDelete(`/admin/reports/${row.id}`);ElMessage.success('已删除');await load()}
onMounted(load)
</script>
<template><PageHeader title="导出报表" group="数据中心" description="v1.0 提供任务管理，文件异步生成在后续版本接入"><el-button v-if="auth.hasPermission('report:write')" class="lime-button" @click="dialog=true">+ 新建导出任务</el-button></PageHeader><KpiGrid :items="kpis" :loading="loading"/><section class="panel"><div class="panel__toolbar"><span class="panel__title">报表任务</span><el-button :loading="loading" @click="load">刷新</el-button></div><el-table :data="items" v-loading="loading"><el-table-column prop="name" label="任务名称" min-width="220"/><el-table-column prop="type" label="数据类型" width="110"/><el-table-column prop="dateRange" label="时间范围" width="150"/><el-table-column prop="dimension" label="维度" width="100"/><el-table-column prop="creator" label="创建人" width="150"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.status==='done'?'success':row.status==='processing'?'warning':'danger'">{{row.status==='done'?'已完成':row.status==='processing'?'处理中':'失败'}}</el-tag></template></el-table-column><el-table-column label="创建时间" width="180"><template #default="{row}">{{new Date(row.createdAt).toLocaleString('zh-CN',{hour12:false})}}</template></el-table-column><el-table-column v-if="auth.hasPermission('report:write')" label="操作" width="100"><template #default="{row}"><el-button size="small" type="danger" plain @click="remove(row)">删除</el-button></template></el-table-column></el-table></section><el-dialog v-model="dialog" title="新建导出任务" width="500px"><el-form label-position="top"><el-form-item label="任务名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="数据类型"><el-select v-model="form.type" style="width:100%"><el-option label="路线数据" value="route"/><el-option label="用户数据" value="user"/><el-option label="加油站/油价" value="fuel"/><el-option label="内容数据" value="ugc"/></el-select></el-form-item><el-form-item label="时间范围"><el-input v-model="form.dateRange"/></el-form-item><el-form-item label="统计维度"><el-input v-model="form.dimension"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button v-if="auth.hasPermission('report:write')" type="primary" :disabled="!form.name" @click="create">创建任务</el-button></template></el-dialog></template>
